CREATE OR REPLACE FUNCTION private.log_staff_profile_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN IF auth.uid() IS NOT NULL THEN INSERT INTO public.activity_logs(actor_id,action,entity_type,entity_id,metadata) VALUES(auth.uid(),'staff_profile_update','staff_profiles',NEW.user_id,jsonb_build_object('fields',jsonb_build_array('display_name','phone'),'old',jsonb_build_object('display_name',OLD.display_name,'phone',OLD.phone),'new',jsonb_build_object('display_name',NEW.display_name,'phone',NEW.phone))); END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION private.log_staff_profile_change() FROM PUBLIC;
